const CLASS_TO_COUNT = {
  1: "road",
  2: "lm_solid",
  3: "lm_dashed",
};

const countIOU = (groundTruth, prediction) => {
  const stats = {};
  
  Object.keys(CLASS_TO_COUNT).forEach((classId) => {
    stats[classId] = { 
      name: CLASS_TO_COUNT[classId], 
      tp: 0, 
      fp: 0, 
      fn: 0, 
      iou: 0 
    };
  });

  const height = groundTruth.length;
  const width = groundTruth[0].length;

  // Iterate through each pixel
  for (let i = 0; i < height; i++) {
    for (let j = 0; j < width; j++) {
      const gtVal = groundTruth[i][j];
      const predVal = prediction[i][j];

      Object.keys(CLASS_TO_COUNT).forEach((key) => {
        const classId = Number(key);
        
        if (gtVal === classId && predVal === classId) {
          stats[classId].tp++;
        } else if (gtVal !== classId && predVal === classId) {
          stats[classId].fp++;
        } else if (gtVal === classId && predVal !== classId) {
          stats[classId].fn++;
        }
      });
    }
  }

  // Count IoU for each class
  Object.keys(stats).forEach((key) => {
    const { tp, fp, fn } = stats[key];
    const union = tp + fp + fn;
    
    stats[key].iou = union === 0 ? 0 : tp / union;
  });

  return stats;
};

const results = countIOU(GROUND_TRUTH_MASK, PREDICTION_MASK);
console.log(results);
